// Design system adherence, wired in before the first component exists on purpose.
//
// `.claude/skills/offload-design/_adherence.oxlintrc.json` is the machine-readable
// version of the token rules. It is GENERATED by the design system and must never be
// hand-edited, so this file reads it at run time rather than copying anything out of
// it. Regenerating it on the next design sync propagates here with no edit.
//
// Two things about that file are worth knowing:
//
//  1. Despite the name it does not run under oxlint. oxlint 1.80 rejects it twice
//     over: it refuses the non-schema `x-omelette` key, and it does not implement
//     `no-restricted-syntax`, which is the rule carrying every token and prop check.
//     ESLint core implements both rules, and we were already on ESLint, so this is
//     where the config actually earns its keep. See docs/tech/decisions.md.
//  2. It gives us four families of check: restricted imports (do not reach into
//     component internals), raw hex colours, raw px values, and the prop contract of
//     all 21 components including the allowed values of every enum prop.

import { createRequire } from "node:module";

const require = createRequire(import.meta.url);
const adherence = require("./.claude/skills/offload-design/_adherence.oxlintrc.json");

// [severity, ...options]. Drop the design system's severity and use our own.
const options = (rule) => {
  const entry = adherence.rules?.[rule];
  return Array.isArray(entry) ? entry.slice(1) : null;
};

const restrictedSyntax = options("no-restricted-syntax");
const restrictedImports = options("no-restricted-imports");

const adherenceRules = {};
if (restrictedSyntax) adherenceRules["no-restricted-syntax"] = ["error", ...restrictedSyntax];
if (restrictedImports) adherenceRules["no-restricted-imports"] = ["error", ...restrictedImports];

export default [
  {
    ignores: [
      // The design system owns its own files and its kits break these rules by design.
      ".claude/skills/offload-design/**",
      "**/node_modules/**",
      "**/dist/**",
      "**/build/**",
      "**/.next/**",
      "**/.expo/**",
      // The generated token module is the one place a raw hex and a raw px belong,
      // because it is what every other file references instead of retyping them.
      "packages/tokens/generated/**",
    ],
  },
  {
    files: ["**/*.{js,jsx,mjs,cjs,ts,tsx}"],
    languageOptions: {
      ecmaVersion: "latest",
      sourceType: "module",
      parserOptions: { ecmaFeatures: { jsx: true } },
    },
    rules: adherenceRules,
  },
];
